				Class* o = dynamic_cast<Class*>(instance);
				if (!o)
					throw std::bad_cast();

				call<typename result_type>(o, arguments.returnValue);
			}

		private:
			template<typename ReturnType>
			void call(Class* o, Value& returnValue) const
			{
				returnValue.set<ReturnType>((o->*function)());
