		{
			std::for_each(chatHistory.begin(), chatHistory.end(), boost::bind(&AbuseReport::addMessage, boost::ref(r), _1));

			{
				boost::mutex::scoped_lock lock(_data->requestSync);
				_data->queue.push(r);
			}

			requestProcessor->wake();
