    }

    renderDevice->beginPrimitive(RenderDevice::QUADS);
        vertex(renderDevice, +s, +s, +s, 0, 0);
        vertex(renderDevice, +s, -s, +s, 0, 1);
        vertex(renderDevice, -s, -s, +s, 1, 1);
        vertex(renderDevice, -s, +s, +s, 1, 0);
