CWnd* CXTPToolTipContext::CreateToolTip(CWnd* /*pOwner*/)
{
	switch (m_toolStyle)
	{
	case xtpToolTipOffice:
		return new CXTPToolTipContextToolTip(this);

	case xtpToolTipRTF:
		return new CRichEditToolTip(this);

	case xtpToolTipLuna:
